css:
.morse-sleep {
  position: relative;
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  background: none;
  color: var(--text-subdued, #b3b3b3);
  cursor: pointer;
}
.morse-sleep:hover { color: var(--text-base, #fff); }
.morse-sleep.on { color: var(--text-bright-accent, #1ed760); }
.morse-sleep span {
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  padding: 3px 6px;
  border-radius: 9px;
  background: var(--text-bright-accent, #1ed760);
  color: #000;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

js:
const STEPS = [15, 30, 60, 0];
let left = 0;
let i = STEPS.indexOf(morse.store.get("last", 0)) - 1;

morse.watch('[data-testid="control-button-repeat"]', repeat => {
  const label = morse.el("span");
  const moon = '<svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor"><path d="M6 1a7 7 0 1 0 9 9A6 6 0 0 1 6 1z"/></svg>';
  const btn = morse.el("button", {
    class: "morse-sleep", "aria-label": "Sleep timer", title: "Sleep timer", html: moon,
    on: { click() {
      i = (i + 1) % STEPS.length;
      left = STEPS[i] * 60;
      morse.store.set("last", STEPS[i]);
      render();
      morse.toast(left ? "Pausing in " + STEPS[i] + " minutes" : "Sleep timer off");
    } },
  });
  const render = () => {
    btn.classList.toggle("on", left > 0);
    label.textContent = Math.floor(left / 60) + ":" + String(left % 60).padStart(2, "0");
    if (left) btn.append(label); else label.remove();
  };
  morse.every(1000, () => {
    if (!left) return;
    if (--left === 0) {
      const pp = document.querySelector('[data-testid="control-button-playpause"]');
      if (pp && pp.getAttribute("aria-label") === "Pause") pp.click();
      morse.toast("Sleep timer: paused");
    }
    render();
  });
  repeat.after(btn);
});
